                        if grid[nx][ny] == '#':
                            grid[nx][ny] = color
                            placed += 1
                            queue.append((nx, ny))

    # Place A white components
    for _ in range(A):
        place_component(1, '.')

    # Place B black components
    for _ in range(B):
        place_component(1, '#')

    return h, w, grid

