import random
import math

def generate_grid(A, B):
    total = A + B
    h = int(math.sqrt(total))
    w = (total + h - 1) // h  # Ceiling division

    grid = [['#' for _ in range(w)] for _ in range(h)]

    def is_valid(x, y):
        return 0 <= x < h and 0 <= y < w

    def dfs(x, y, color):
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            if grid[cx][cy] != '#':
                continue
            grid[cx][cy] = color
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = cx + dx, cy + dy
                if is_valid(nx, ny) and grid[nx][ny] == '#':
                    stack.append((nx, ny))

    def place_components(count, color):
        placed = 0
        while placed < count:
            x, y = random.randint(0, h-1), random.randint(0, w-1)
            if grid[x][y] == '#':
                dfs(x, y, color)
                placed += 1

    place_components(A, '.')
    place_components(B, '#')

    return h, w, grid

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    A = int(data[0])
    B = int(data[1])

    h, w, grid = generate_grid(A, B)

    print(h, w)
    for row in grid:
        print(''.join(row))

